//! 🩹️ Sparse native material patches share original sealed fields and receive only explicitly authored text.
use semio_framework_value::{Number, OriginalRetirementFailure, RetainedAllocationEffect, RetainedWorkPoll, RetirementDemand, ValueError, ValueRefusalKind, retained_clone::{OriginalEffectReply, OriginalEffectReplyComplete, RetainedCloneBinding, RetainedCloneClose, RetainedCloneGrant, RetainedCloneProgress, RetainedCloneRef, RetainedCloneStep, retained_clone_grant_admits}, shared_issuance::{SealedShared, SharedIssuer}};
use semio_framework_value_native_owned::{native_decoding::{NativeDecodeControl, NativeReceivingFailure, NativeSharedAdmission}, native_decoding::owned::{NativeIntrinsicSharedField, native_close_begun, native_close_denied, native_reply_poll}};
use std::mem::ManuallyDrop;
use std::mem::size_of;
/// 👓️ A genuine native material row lends its actual sealed fields and fixed scalar values.
pub trait NativeMaterialRow<const N:usize>:semio_framework_value::retirement::RetireOwned+Send+Sync+'static{
 fn texts(&self)->[&SealedShared<String>;2];
 fn numbers(&self)->[Number;N];
 fn validation_demand(texts:[&str;2],numbers:[Number;N])->RetirementDemand;
 fn validate_parts(texts:[&str;2],numbers:[Number;N])->Result<(),ValueError>;
 fn from_parts(texts:[SealedShared<String>;2],numbers:[Number;N])->Self;
}
/// 📋️ Canonical sparse authoring values lend the original name and scalar presence without conversion.
pub trait NativeMaterialPatch<const N:usize>:Sync+'static{fn name(&self)->Option<&String>;fn numbers(&self)->[Option<f64>;N];}
/// 🧳️ Both original sources and every partial changed field remain retained until funded transfer or cancellation.
pub struct NativeMaterialPatchCursor<P:NativeMaterialPatch<N>,R:NativeMaterialRow<N>,const N:usize>{row:Option<RetainedCloneBinding>,patch:Option<RetainedCloneBinding>,texts:ManuallyDrop<[Option<SealedShared<String>>;2]>,name:NativeIntrinsicSharedField<String>,raw:ManuallyDrop<Option<R>>,output:ManuallyDrop<Option<SealedShared<R>>>,admission:NativeSharedAdmission<R>,retirement:RetainedCloneClose,phase:u8,closing:bool,input:std::marker::PhantomData<fn()->P>}
fn primary(p:semio_framework_value_native_owned::OriginalReceivingPrimary)->ValueError{p.primary.or(p.quote_refusal).or(p.allocation_refusal).unwrap_or_else(invalid)}
fn retired(f:OriginalRetirementFailure)->ValueError{let progress=f.retained_progress();let(primary,work,receipt,..)=f.into_parts();primary.or(work).or(receipt).unwrap_or_else(invalid).with_retained_progress(progress)}
fn native(failure:NativeReceivingFailure)->ValueError{match failure{NativeReceivingFailure::Primary(p)=>primary(p),NativeReceivingFailure::ValueEffect(e)=>e.child.or(e.producer_refusal).or(e.work_refusal).unwrap_or_else(||primary(e.receiving)),NativeReceivingFailure::RetirementEffect(e)=>e.child.map(retired).or(e.producer_refusal).or(e.work_refusal).unwrap_or_else(||primary(e.receiving)),NativeReceivingFailure::ReceivingEffect(e)=>e.child.map(primary).or(e.producer_refusal).or(e.work_refusal).unwrap_or_else(||primary(e.receiving))}}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native Material patch lacks its exact original sources or funded phase")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand,extra:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(extra).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
fn child(g:RetainedCloneGrant,extra:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-extra,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl<P:NativeMaterialPatch<N>,R:NativeMaterialRow<N>,const N:usize> NativeMaterialPatchCursor<P,R,N>{
 pub fn birth_demand()->RetirementDemand{fixed(size_of::<Self>()*2)}
 pub fn begin(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid());}Ok((Self{row:None,patch:None,texts:ManuallyDrop::new([None,None]),name:Default::default(),raw:ManuallyDrop::new(None),output:ManuallyDrop::new(None),admission:Default::default(),retirement:Default::default(),phase:0,closing:false,input:std::marker::PhantomData},receipt(d)))}
 fn metadata()->usize{2*size_of::<u8>()+2*size_of::<Option<SealedShared<String>>>()}
 fn values(row:&R,patch:&P)->[Number;N]{let values=row.numbers();let updates=patch.numbers();std::array::from_fn(|i|updates[i].map(Number::Float).unwrap_or(values[i]))}
 fn original_name<'a>(patch:RetainedCloneRef<'a,P>)->RetainedCloneRef<'a,String>{patch.project(1,|p|p.name().expect("genuine authored sparse material name"))}
 pub fn demand(&self,row:RetainedCloneRef<'_,R>,patch:RetainedCloneRef<'_,P>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{
  if self.closing||self.phase>=7{return Err(invalid());}row.check_binding(&self.row)?;patch.check_binding(&self.patch)?;let m=Self::metadata();
  match self.phase{0=>Ok(fixed(row.binding_copy_bytes()+m)),1=>Ok(fixed(patch.binding_copy_bytes()+m)),2=>Ok(fixed(size_of::<SealedShared<String>>()*2+m)),3=>if patch.get().name().is_some(){nested(if self.name.ready(){self.name.take_demand()?}else{self.name.demands(Self::original_name(patch),body,maximum_work_units)?},m)}else{Ok(fixed(size_of::<SealedShared<String>>()*2+m))},4=>{let texts=row.get().texts();let numbers=Self::values(row.get(),patch.get());nested(R::validation_demand([texts[0].as_str(),texts[1].as_str()],numbers),size_of::<[Number;N]>()*2+size_of::<[Option<f64>;N]>()+m)},5=>Ok(fixed(size_of::<R>()*2+size_of::<[Number;N]>()*2+size_of::<[Option<f64>;N]>()+m)),6=>nested(semio_framework_value_native_owned::native_decoding::NativeOwnedDecodeControl::shared_birth_demand::<R>(),m),_=>Err(invalid())}
 }
 pub fn advance(&mut self,row:RetainedCloneRef<'_,R>,patch:RetainedCloneRef<'_,P>,control:&mut NativeDecodeControl<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>)->Result<RetainedCloneStep,ValueError>{
  let g=effect.grant();let d=self.demand(row,patch,body,effect.maximum_work_units())?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}control.checkpoint()?;let m=Self::metadata();let mut p=receipt(d);
  match self.phase{0=>{row.bind(&mut self.row,&mut effect.nested(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-m,..g})).result?.ok_or_else(invalid)?;self.phase=1;},1=>{patch.bind(&mut self.patch,&mut effect.nested(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-m,..g})).result?.ok_or_else(invalid)?;self.phase=2;},2=>{self.texts[0]=Some(row.get().texts()[0].try_duplicate(effect).result?.0);self.phase=3;},3 if patch.get().name().is_some()=>{let step=if self.name.ready(){let mut name=None;let step=match self.name.take(&mut name,&mut effect.nested(child(g,m))){RetainedWorkPoll::Pending{..}=>return Ok(RetainedCloneStep::Progress(Default::default())),RetainedWorkPoll::Complete(turn)=>turn.result.map_err(primary)?};self.texts[1]=Some(name.ok_or_else(invalid)?);self.phase=4;RetainedCloneStep::Progress(step.progress())}else{match self.name.advance(Self::original_name(patch),control,body,effect.maximum_work_units(),child(g,m)){RetainedWorkPoll::Pending{..}=>return Ok(RetainedCloneStep::Progress(Default::default())),RetainedWorkPoll::Complete(turn)=>turn.result.map_err(|e|{let mut p=e.retained_progress();p.copied_bytes=p.copied_bytes.saturating_add(m);native(e).with_retained_progress(p)})?}};p=step.progress();p.copied_bytes=p.copied_bytes.checked_add(m).ok_or_else(invalid)?;},3=>{self.texts[1]=Some(row.get().texts()[1].try_duplicate(effect).result?.0);self.phase=4;},4=>{effect.performed(1)?;R::validate_parts([self.texts[0].as_ref().ok_or_else(invalid)?.as_str(),self.texts[1].as_ref().ok_or_else(invalid)?.as_str()],Self::values(row.get(),patch.get())).map_err(|e|e.with_retained_progress(p))?;self.phase=5;},5=>{effect.performed(1)?;let[id,name]=std::mem::replace(&mut*self.texts,[None,None]);*self.raw=Some(R::from_parts([id.ok_or_else(||ValueError::invariant("id absent"))?,name.ok_or_else(||ValueError::invariant("name absent"))?],Self::values(row.get(),patch.get())));self.phase=6;},6=>{let turn=control.receive_shared(&mut self.raw,&mut self.output,SharedIssuer::owned(),&mut self.admission);p=turn.result.map_err(primary)?;if self.output.is_some(){self.phase=7;}},_=>return Err(invalid())}
  semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"native Material sparse patch")?;Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})
 }
 pub fn ready(&self)->bool{!self.closing&&self.phase==7&&self.output.is_some()}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid());}Ok(fixed(size_of::<Option<SealedShared<R>>>()*2+size_of::<u8>()))}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(SealedShared<R>,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None);}self.phase=8;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d))))}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if !self.name.terminal_is_empty(){return if self.name.is_closing(){self.name.close_demands(body)}else{self.name.begin_close_demand()};}if !self.admission.terminal_is_empty(){return self.admission.close_demand();}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<R>(false,&None,body);}if self.texts.iter().any(Option::is_some){return self.retirement.next_owner_demands::<SealedShared<String>>(true,&None,body);}if self.raw.is_some(){return self.retirement.next_owner_demands::<R>(true,&None,body);}if self.output.is_some(){return self.retirement.next_owner_demands::<SealedShared<R>>(true,&None,body);}RetainedCloneBinding::close_demand(if self.patch.is_some(){&self.patch}else{&self.row},body)}
 pub fn close_step<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_route(body,effect,reply,false)}
 pub fn recover_close_step<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_route(body,effect,reply,true)}
 fn close_route<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{
  if !self.name.terminal_is_empty(){return match(self.name.is_closing(),recover){(false,false)=>self.name.begin_close_into(effect,reply),(false,true)=>self.name.recover_begin_close_into(effect,reply),(true,false)=>self.name.close_step(body,effect,reply),(true,true)=>self.name.recover_close_step(body,effect,reply)};}
  let g=effect.grant();let d=match self.close_demand(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return Ok(reply.complete(Err(error.into())))};if !retained_clone_grant_admits(g,d){return native_close_denied(reply);}
  if !self.admission.terminal_is_empty(){return Ok(native_reply_poll(self.admission.close_step(effect),reply));}
  if !self.retirement.is_empty(){return if recover{self.retirement.recover_step_into(body,effect,reply)}else{self.retirement.step_into(body,effect,reply)};}
  for text in self.texts.iter_mut(){if text.is_some(){return native_close_begun(self.retirement.begin_granted(text,effect),reply);}}
  if self.raw.is_some(){return native_close_begun(self.retirement.begin_granted(&mut self.raw,effect),reply);}
  if self.output.is_some(){return native_close_begun(self.retirement.begin_granted(&mut self.output,effect),reply);}
  Ok(native_reply_poll(RetainedCloneBinding::close_one(if self.patch.is_some(){&mut self.patch}else{&mut self.row},body,effect),reply))
 }
 pub fn terminal_is_empty(&self)->bool{self.row.is_none()&&self.patch.is_none()&&self.texts.iter().all(Option::is_none)&&self.raw.is_none()&&self.output.is_none()&&self.admission.terminal_is_empty()&&self.retirement.is_empty()&&self.name.terminal_is_empty()}
}
impl<P:NativeMaterialPatch<N>,R:NativeMaterialRow<N>,const N:usize> Drop for NativeMaterialPatchCursor<P,R,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native Material patch retains all original and candidate issuers until funded close");}}
